const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define a rough polygon for Petén, Guatemala
    const peten = ee.Geometry.Polygon(
      [[[-91.70, 16.03],
        [-91.70, 17.80],
        [-88.70, 17.80],
        [-88.70, 16.03],
        [-91.70, 16.03]]]);

    const year2001 = 1; // Represents 2001 in Hansen's lossyear (1 means 2001 loss)
    const year2023 = 23; // Represents 2023 in Hansen's lossyear

    // 2. Data Acquisition
    const gfc = ee.Image('UMD/hansen/global_forest_change_v1_11');

    // Check if the Hansen GFC image exists
    if (!gfc) {
      console.log("Error: Could not load UMD/hansen/global_forest_change_v1_11.");
      console.log("D"); // Data loading failure
      return;
    }

    const treeCover = gfc.select('treecover2000');
    const loss = gfc.select('loss');
    const lossYear = gfc.select('lossyear');

    // Define forest as pixels with at least 10% tree cover in 2000
    const forestThreshold = 10;
    const initialForest = treeCover.gte(forestThreshold);

    // Calculate pixel area for area computation
    const pixelArea = ee.Image.pixelArea().updateMask(initialForest);
    const scale = 1000; // Use a reasonable scale for calculation (meters)

    // 3. Processing - Forest Cover 2001
    // Forest in 2001 is initial forest minus any loss that occurred in 2001 (lossyear == 1)
    const forest2001Mask = initialForest.and(lossYear.neq(year2001));
    const forest2001 = pixelArea.updateMask(forest2001Mask);

    // Calculate valid pixel count for 2001
    const count2001 = forest2001.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: peten,
      scale: scale,
      maxPixels: 1e9
    }).values().get(0).getInfo();

    if (count2001 === null || count2001 === 0) {
      console.log("No valid pixels for 2001 after masking in Petén.");
      console.log("C2");
      return;
    }

    // 4. Processing - Forest Cover 2023
    // Forest in 2023 is initial forest minus any loss that occurred up to 2023 (lossyear <= 23)
    const forest2023Mask = initialForest.and(lossYear.eq(0).or(lossYear.gt(year2023)));
    const forest2023 = pixelArea.updateMask(forest2023Mask);

    // Calculate valid pixel count for 2023
    const count2023 = forest2023.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: peten,
      scale: scale,
      maxPixels: 1e9
    }).values().get(0).getInfo();

    if (count2023 === null || count2023 === 0) {
      console.log("No valid pixels for 2023 after masking in Petén.");
      console.log("C2");
      return;
    }

    // 5. Calculation of Forest Area
    const forestArea2001SqM = forest2001.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: peten,
      scale: scale,
      maxPixels: 1e9
    }).values().get(0).getInfo();

    const forestArea2023SqM = forest2023.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: peten,
      scale: scale,
      maxPixels: 1e9
    }).values().get(0).getInfo();

    // Check for calculation failures (None/NaN)
    if (forestArea2001SqM === null || forestArea2023SqM === null ||
        isNaN(forestArea2001SqM) || isNaN(forestArea2023SqM)) {
      console.log("Calculation of forest area failed (result is null or NaN).");
      console.log("C3");
      return;
    }

    // Convert to square kilometers for readability
    const forestArea2001SqKm = forestArea2001SqM / 1e6;
    const forestArea2023SqKm = forestArea2023SqM / 1e6;

    console.log(`Forest Area 2001 (sq km): ${forestArea2001SqKm.toFixed(2)} (Pixels: ${count2001})`);
    console.log(`Forest Area 2023 (sq km): ${forestArea2023SqKm.toFixed(2)} (Pixels: ${count2023})`);

    // 6. Validation & Final Answer
    if (forestArea2023SqKm < forestArea2001SqKm) {
      console.log("A"); // Yes, forest cover decreased
    } else {
      console.log("B"); // No, forest cover did not decrease or stayed the same/increased
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    if (error.message.includes("does not exist") || error.message.includes("ImageCollection.filter")) {
      console.log("C1"); // Likely an issue with data availability or filtering
    } else {
      console.log("D"); // General execution or syntax error
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
